import os
import re

PAGES_DIR = "/Users/samforeman/projects/saforem2/sam.onl/web/src/pages"
WEB_DIR = "/Users/samforeman/projects/saforem2/sam.onl/web"
PUBLIC_DIR = "/Users/samforeman/projects/saforem2/sam.onl/web/public"
SRC_DIR = "/Users/samforeman/projects/saforem2/sam.onl/web/src"

files = []
for root, dirs, fnames in os.walk(PAGES_DIR):
    for f in fnames:
        if f.endswith(('.mdx', '.md', '.astro')):
            files.append(os.path.join(root, f))

def is_local(path):
    return path and not path.startswith(('http://', 'https://', 'data:', '#', 'mailto:', '//', '{'))

def resolve_and_check(ref_path, file_path):
    ref_path = ref_path.strip()
    if ref_path.startswith('/'):
        candidates = [
            os.path.join(PUBLIC_DIR, ref_path.lstrip('/')),
            os.path.join(WEB_DIR, ref_path.lstrip('/')),
            os.path.join(SRC_DIR, ref_path.lstrip('/')),
            os.path.join(PAGES_DIR, ref_path.lstrip('/')),
        ]
    elif ref_path.startswith('@/'):
        candidates = [os.path.join(SRC_DIR, ref_path[2:])]
    elif ref_path.startswith('~/'):
        candidates = [os.path.join(SRC_DIR, ref_path[2:])]
    else:
        file_dir = os.path.dirname(file_path)
        candidates = [os.path.normpath(os.path.join(file_dir, ref_path))]
    for c in candidates:
        if os.path.exists(c):
            return True, c
    return False, candidates[0] if candidates else ref_path

IMG_EXTS = ('.png', '.jpg', '.jpeg', '.gif', '.svg', '.webp', '.avif', '.bmp', '.ico', '.tiff')

broken = []

for fpath in sorted(files):
    with open(fpath, 'r', errors='replace') as f:
        content = f.read()

    # Find all <img> tags including multi-line ones
    for m in re.finditer(r'<img\b((?:[^>]|\n)*?)/?>', content, re.I | re.S):
        tag = m.group(0)
        src_m = re.search(r'\bsrc\s*=\s*["\']([^"\']*)["\']', tag, re.I)
        if not src_m:
            continue
        path = src_m.group(1)
        if not is_local(path):
            continue

        # Calculate line number
        start = m.start()
        lineno = content[:start].count('\n') + 1

        exists, resolved = resolve_and_check(path, fpath)
        if not exists:
            broken.append((fpath, lineno, path, resolved, tag.replace('\n', ' ')[:200]))

    # Find all markdown image refs including multi-line (shouldn't be, but just in case)
    for m in re.finditer(r'!\[([^\]]*)\]\(([^)\s]+)', content):
        path = m.group(2)
        if not is_local(path):
            continue
        start = m.start()
        lineno = content[:start].count('\n') + 1
        exists, resolved = resolve_and_check(path, fpath)
        if not exists:
            broken.append((fpath, lineno, path, resolved, m.group(0)[:200]))

    # Find import statements for image files
    for m in re.finditer(r'import\s+(\w+)\s+from\s+["\']([^"\']+)["\']', content):
        path = m.group(2)
        if not any(path.lower().endswith(e) for e in IMG_EXTS):
            continue
        if not is_local(path):
            continue
        start = m.start()
        lineno = content[:start].count('\n') + 1
        exists, resolved = resolve_and_check(path, fpath)
        if not exists:
            broken.append((fpath, lineno, path, resolved, m.group(0)[:200]))

# Deduplicate
seen = set()
unique_broken = []
for b in broken:
    key = (b[0], b[1], b[2])
    if key not in seen:
        seen.add(key)
        unique_broken.append(b)

print(f"Broken image references (multi-line aware): {len(unique_broken)}")
for i, (fpath, lineno, path, resolved, ref) in enumerate(unique_broken, 1):
    print(f"\n--- #{i} ---")
    print(f"  File:     {fpath}")
    print(f"  Line:     {lineno}")
    print(f"  Path:     {path}")
    print(f"  Resolved: {resolved}")
    print(f"  Ref:      {ref}")

if not unique_broken:
    print("None found. All image references point to existing files.")

